import fs from "fs";
import path from "path";
import dev from "./now.dev.mjs";

dev({
  rootDir: path.resolve("."),
  config: JSON.parse(fs.readFileSync("now.config.json", "utf-8")),
  fs,
  path,
  logger: console,
  credential: {
    getUrl: () => new URL("http://localhost:8080"),
    getHeaders: async () => ({
      Authorization: `Basic ${Buffer.from("admin:admin").toString("base64")}`,
    }),
  },
});
